from pathlib import Path
from bs4 import BeautifulSoup
root=Path('/mnt/data/work')
# Update quick-access links on every HTML page that has the top social zone links.
for p in root.glob('*.html'):
    s=p.read_text(errors='ignore')
    if 'class="socialIconTop"' not in s:
        continue
    s=s.replace('href="#" target="_blank">                Parent\'s Zone', 'href="parent-zone.html">                Parent\'s Zone')
    s=s.replace('href="teacher.html">                Teacher\'s Zone', 'href="teacher-zone.html">                Teacher\'s Zone')
    # Normalize if whitespace/newline differs is handled with regex below.
    import re
    s=re.sub(r'(<div class="socialIconTop">\s*<ul>\s*<li class="TeacherZone">\s*<a[^>]*href=")[^"]*("[^>]*>\s*Parent\'s Zone)', r'\1parent-zone.html\2', s, count=1, flags=re.S)
    s=re.sub(r'(<div class="socialIconTop">.*?<li class="TeacherZone">\s*<a[^>]*href=")[^"]*("[^>]*>\s*Teacher\'s Zone)', r'\1teacher-zone.html\2', s, count=1, flags=re.S)
    p.write_text(s)

# Build public teacher directory from the exact teacher/staff cards in index.html.
index=BeautifulSoup((root/'index.html').read_text(errors='ignore'),'html.parser')
section_heading=None
for h2 in index.find_all('h2'):
    if 'Teacher' in ' '.join(h2.stripped_strings) and 'Staff' in ' '.join(h2.stripped_strings):
        section_heading=h2.parent.parent
        break
# Extract cards by class.
teacher_cards=[]
for card in index.select('.incharge-card'):
    name=card.select_one('.incharge-content h4')
    img=card.select_one('.incharge-image img')
    badge=card.select_one('.badge-campus')
    if not name or not img: continue
    info=[x.get_text(' ',strip=True) for x in card.select('.info-box p')]
    teacher_cards.append((name.get_text(' ',strip=True), img.get('src',''), badge.get_text(' ',strip=True) if badge else '', info))
# First 7 are teaching personnel; rest staff based on badge.
teachers=[x for x in teacher_cards if x[2].strip().lower() not in {'staff'}]
staff=[x for x in teacher_cards if x[2].strip().lower()=='staff']

def esc(s):
    return (s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;'))

def cards_html(items):
    out=[]
    for name,img,badge,info in items:
        designation=''
        subject=''
        shift=''
        for text in info:
            low=text.lower()
            if 'subject:' in low:
                subject=text.split(':',1)[1].strip()
            elif 'designation:' in low:
                designation=text.split(':',1)[1].strip()
            elif 'shift:' in low:
                shift=text.split(':',1)[1].strip()
        role=subject or designation or badge
        out.append(f'''<div class="person-card"><div class="person-photo"><img src="{esc(img)}" alt="{esc(name)}" loading="lazy"></div><div class="person-body"><div class="person-top"><h3>{esc(name)}</h3><span>{esc(badge)}</span></div><div class="person-meta">{'<p><i class="fa-solid fa-book"></i>'+esc(role)+'</p>' if role else ''}{'<p><i class="fa-regular fa-clock"></i>'+esc(shift)+'</p>' if shift else ''}</div></div></div>''')
    return '\n'.join(out)

