# Teacher secure portal connected to existing Supabase configuration.
(root/'teacher-zone.html').write_text('''<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher's Zone | Abdul Hossain High School</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script src="supabase-config.js"></script><style>:root{--p:#06319c;--p2:#0b5bd3;--ink:#17213a;--muted:#6b7280}body{margin:0;font-family:Poppins,Arial,sans-serif;background:#f6f8fc;color:var(--ink)}.top{background:linear-gradient(135deg,var(--p),var(--p2));color:#fff;padding:16px 0}.container{width:min(1100px,92%);margin:auto}.nav{display:flex;gap:10px;flex-wrap:wrap}.nav a{color:#fff;text-decoration:none;border:1px solid rgba(255,255,255,.25);padding:8px 13px;border-radius:999px;background:rgba(255,255,255,.1)}.hero{padding:45px 0}.hero h1{font-size:38px;font-weight:800}.card{background:#fff;border:1px solid #e7ecf5;border-radius:18px;box-shadow:0 10px 30px rgba(20,40,90,.08);padding:28px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.tile{background:linear-gradient(135deg,#fff,#f2f6ff);border:1px solid #e0e8f7;border-radius:16px;padding:20px}.tile i{font-size:26px;color:var(--p);margin-bottom:12px}.btn{border:0;border-radius:10px;padding:11px 18px;background:linear-gradient(135deg,var(--p),var(--p2));color:#fff;font-weight:700;cursor:pointer}.btn.alt{background:#eef4ff;color:var(--p)}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d8e0ef;border-radius:10px;margin:8px 0 14px}label{font-weight:700;font-size:13px}.hidden{display:none!important}.msg{padding:12px;border-radius:10px;background:#fff4d8;color:#795b00;margin-top:12px}.error{background:#ffe8e8;color:#a50000}@media(max-width:700px){.grid{grid-template-columns:1fr}.hero h1{font-size:30px}}</style></head><body><header class="top"><div class="container"><div class="nav"><a href="index.html"><i class="fa-solid fa-house"></i> Home</a><a href="parent-zone.html">Parent's Zone</a><a href="teacher.html">Teacher</a><a href="admin.html">Admin Zone</a></div></div></header><main class="container hero"><h1>Teacher's Zone</h1><p>শিক্ষকদের জন্য নিরাপদ সার্ভারভিত্তিক পোর্টাল।</p><section id="loginCard" class="card"><h2>Teacher Login</h2><p>আপনার Supabase account দিয়ে প্রবেশ করুন।</p><label>Email</label><input id="email" type="email" autocomplete="username"><label>Password</label><input id="password" type="password" autocomplete="current-password"><button class="btn" id="loginBtn">Login</button><div id="loginMsg" class="msg hidden"></div></section><section id="dash" class="hidden"><div class="card"><div style="display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap"><div><h2 id="welcome">Teacher Dashboard</h2><p id="roleText" style="color:var(--muted)"></p></div><button class="btn alt" id="logoutBtn">Logout</button></div></div><div class="grid"><div class="tile"><i class="fa-solid fa-calendar-days"></i><h3>Routine</h3><p>Teacher routine ও class schedule দেখুন।</p><a class="btn alt" href="teacher-routine.html">Open</a></div><div class="tile"><i class="fa-solid fa-bullhorn"></i><h3>Notices</h3><p>সর্বশেষ school notice দেখুন।</p><a class="btn alt" href="notice-board.html">Open</a></div><div class="tile"><i class="fa-solid fa-user-graduate"></i><h3>Academic</h3><p>Academic resources ও school information।</p><a class="btn alt" href="academic.html">Open</a></div></div></section></main><script>const sb=supabase.createClient(window.SUPABASE_URL,window.SUPABASE_ANON_KEY);const $=id=>document.getElementById(id);function msg(t,e=false){$('loginMsg').textContent=t;$('loginMsg').classList.remove('hidden');$('loginMsg').classList.toggle('error',e)}async function roleCheck(){const {data:{session}}=await sb.auth.getSession();if(!session){$('loginCard').classList.remove('hidden');$('dash').classList.add('hidden');return}const {data:roles,error}=await sb.from('user_roles').select('role').eq('user_id',session.user.id);if(error){msg('Role যাচাই করা যাচ্ছে না: '+error.message,true);return}const allowed=(roles||[]).some(r=>r.role==='teacher'||r.role==='admin');if(!allowed){await sb.auth.signOut();msg('এই account-এর Teacher permission নেই।',true);return}$('loginCard').classList.add('hidden');$('dash').classList.remove('hidden');$('welcome').textContent='Welcome, '+(session.user.email||'Teacher');$('roleText').textContent='Role: '+(roles||[]).map(r=>r.role).join(' + ')}$('loginBtn').onclick=async()=>{const email=$('email').value.trim(),password=$('password').value;if(!email||!password){msg('Email ও password দিন।',true);return}const {error}=await sb.auth.signInWithPassword({email,password});if(error){msg(error.message,true);return}await roleCheck()};$('logoutBtn').onclick=async()=>{await sb.auth.signOut();location.reload()};sb.auth.onAuthStateChange(()=>setTimeout(roleCheck,0));roleCheck();</script></body></html>''')
